parameters.functionCode:
const jsdom = (html)=>html
  .replace(/<script[\s\S]*?<\/script>/gi,' ')
  .replace(/<style[\s\S]*?<\/style>/gi,' ')
  .replace(/<[^>]+>/g,' ')
  .replace(/\s+/g,' ').trim();
const url = $json.input?.url || '';
const topic = $json.input?.topic || 'General';
const depth = $json.input?.depth || 1;
const text = jsdom(items[0].json);
return [{ json: { run_id: $json.run_id, input: $json.input, url, topic, depth, text } }];

options.headerParametersJson:
={{
  const crypto = require('crypto');
  const body = JSON.stringify({run_id: $json.run_id, kind: 'progress', stage: 'fetched', meta: {url: $json.url}});
  const sig = crypto.createHmac('sha256', 'HMAC_SECRET').update(body).digest('hex');
  return { 'X-Signature': sig, 'Content-Type': 'application/json' };
}}

parameters.bodyParametersJson:
={{ {
  model: $json.input?.model || 'qwen2.5-7b-instruct',
  messages: [
    {role:'system', content: 'You are a concise research assistant. Return clean Markdown with headings, bullets, and a brief executive summary.'},
    {role:'user', content: `Topic: ${$json.topic}\nDepth: ${$json.depth}\nURL: ${$json.url}\n\nExtract the key insights from the following text and write a structured report (Markdown):\n\n${$json.text.slice(0, 15000)}`}
  ],
  temperature: 0.3
} }}

